import { html } from 'lit-html';
import { action } from '@storybook/addon-actions';

export default {
  title: 'Components/GstinInput',
  component: 'bfl-gstin-input',
  tags: ['autodocs'],
  argTypes: {
    name: { control: 'text', description: 'Name of the field', defaultValue: 'gstin' },
    label: { control: 'text', description: 'Label for the input', defaultValue: 'GSTIN' },
    placeholder: { control: 'text', description: 'Placeholder text', defaultValue: 'Enter GSTIN' },
    isRequired: { control: 'boolean', description: 'Marks the field as required', defaultValue: false },
    maxLength: { control: 'number', description: 'Maximum length of the input', defaultValue: 15 },
    value: { control: 'text', description: 'Initial value of the input', defaultValue: '' },
    hasCustomError: { control: 'boolean', description: 'Displays a custom error', defaultValue: false },
    customErrorMessage: { control: 'text', description: 'Custom error message', defaultValue: 'Invalid GSTIN' },
    isInfoPopup: { control: 'boolean', description: 'Displays an info popup', defaultValue: false },
  },
};

const Template = ({
  name,
  label,
  placeholder,
  isRequired,
  maxLength,
  value,
  hasCustomError,
  customErrorMessage,
  isInfoPopup,
}) => html`
  <bfl-gstin-input
    name="${name}"
    label="${label}"
    placeholder="${placeholder}"
    .isRequired="${isRequired}"
    .maxLength="${maxLength}"
    .value="${value}"
    .hasCustomError="${hasCustomError}"
    .customErrorMessage="${customErrorMessage}"
    .isInfoPopup="${isInfoPopup}"
    @inputChanged="${action('inputChanged')}"
    @onPopUp="${action('onPopUp')}"
  ></bfl-gstin-input>
`;

export const Default = Template.bind({});
Default.args = {
  name: 'gstin',
  label: 'GSTIN',
  placeholder: 'Enter GSTIN',
  isRequired: false,
  maxLength: 15,
  value: '',
  hasCustomError: false,
  customErrorMessage: '',
  isInfoPopup: false,
};

export const WithPlaceholder = Template.bind({});
WithPlaceholder.args = {
  ...Default.args,
  placeholder: 'Enter your GSTIN here',
};

export const WithError = Template.bind({});
WithError.args = {
  ...Default.args,
  hasCustomError: true,
  customErrorMessage: 'Invalid GSTIN format',
};

export const WithInfoPopup = Template.bind({});
WithInfoPopup.args = {
  ...Default.args,
  isInfoPopup: true,
};
